_COPY_EXPAND_TILE_SIZE = 256

def _compute_num_programs(total_input_tokens: int, num_query_total: int) -> int:
    """Number of programs to launch for copy_and_expand kernel."""
    init_device_properties_triton()
    # ❌ 用 sum 计算 grid size：kernel 有两个独立 grid-stride loop
    # sum 会启动在两个 loop 中都空闲的 program
    num_blocks_needed = triton.cdiv(
        total_input_tokens + num_query_total, _COPY_EXPAND_TILE_SIZE
    )
    return (min(num_blocks_needed, get_vectorcore_num()),)
